const b = $input.first().json.body || $input.first().json || {};
const op = (b.op || '').toString();
const q = (s) => (s || '').toString().replace(/'/g, "''");
const qi = (v) => { const n = parseInt(v); if (isNaN(n)) throw new Error('bad id'); return n; };
let sql = '';
if (op === 'list') {
  sql = `SELECT g.id, g.name, g.description, COUNT(c.id) AS chunks FROM rag_groups g LEFT JOIN rag_chunks c ON (c.metadata->>'group_id')::int = g.id GROUP BY g.id, g.name, g.description ORDER BY g.id;`;
} else if (op === 'add') {
  const nm = (b.name || '').toString().trim();
  if (!/^[A-Za-z0-9_ก-ฮ-]{2,64}$/u.test(nm)) throw new Error('ชื่อกลุ่มไม่ถูกต้อง (A-Z a-z 0-9 _ - ก-ฮ ยาว 2-64)');
  sql = `INSERT INTO rag_groups (name, description) VALUES ('${nm}', '${q((b.description || '').slice(0, 255))}');`;
} else if (op === 'persona') {
  const code = (b.channel || b.channel_code || '').toString();
  if (!/^[a-z0-9_]{2,32}$/.test(code)) throw new Error('bad channel');
  sql = `UPDATE channel_map SET persona_system = '${q((b.persona || '').slice(0, 4000))}' WHERE channel_code = '${code}'`;
} else if (op === 'delete') {
  sql = `DELETE FROM rag_groups WHERE id = ${qi(b.id)};`;
} else if (op === 'listsources') {
  sql = `SELECT s.id, s.group_id, s.source_type, COALESCE(s.title, '') AS title, COALESCE(s.source_ref, '') AS source_ref, COALESCE(s.image_url, '') AS image_url, s.created_at, (SELECT COUNT(*) FROM rag_chunks c WHERE c.source_id = s.id) AS chunks FROM rag_sources s WHERE s.group_id = ${qi(b.group_id)} ORDER BY s.id DESC;`;
} else if (op === 'deletesource') {
  sql = `WITH d AS (DELETE FROM rag_sources WHERE id = ${qi(b.id)} AND group_id = ${qi(b.group_id)} RETURNING image_url) SELECT (SELECT COUNT(*) FROM d) AS deleted, COALESCE((SELECT image_url FROM d), '') AS image_url;`;
} else if (op === 'stats') {
  sql = `SELECT (SELECT COUNT(*) FROM rag_sources) AS sources, (SELECT COUNT(*) FROM rag_chunks) AS chunks, (SELECT COUNT(*) FROM rag_sources WHERE source_type = 'image') AS images, (SELECT COALESCE(json_agg(json_build_object('name', g.name, 'chunks', (SELECT COUNT(*) FROM rag_chunks c WHERE (c.metadata->>'group_id')::int = g.id)) ORDER BY g.id), '[]') FROM rag_groups g) AS groups`;} else { throw new Error('unknown op'); }
return [{ json: { sql: sql, op: op } }];

const op = $('Build SQL').first().json.op || '';
const rows = $input.all().map(r => r.json);
if (op === 'list') return [{ json: { ok: true, groups: rows.map(r => ({ ...r, chunks: parseInt(r.chunks) || 0 })) } }];
if (op === 'listsources') return [{ json: { ok: true, sources: rows.map(r => ({ id: parseInt(r.id) || 0, group_id: parseInt(r.group_id) || 0, source_type: (r.source_type || '').toString(), title: (r.title || '').toString(), source_ref: (r.source_ref || '').toString(), image_url: (r.image_url || '').toString(), created_at: (r.created_at || '').toString(), chunks: parseInt(r.chunks) || 0 })) } }];
if (op === 'deletesource') { const r = rows[0] || {}; return [{ json: { ok: true, deleted: (parseInt(r.deleted) || 0) > 0, image_url: (r.image_url || '').toString() } }]; }
if (op === 'stats') {
  const r = rows[0] || {};
  const groups = Array.isArray(r.groups) ? r.groups : [];
  return [{ json: { ok: true, sources: parseInt(r.sources) || 0, chunks: parseInt(r.chunks) || 0, images: parseInt(r.images) || 0,
    groups: groups.map(g => ({ name: g.name, chunks: parseInt(g.chunks) || 0 })) } }];
}
return [{ json: { ok: true } }];
